export const WELD_LEGS = [4, 5, 6, 7, 8, 9, 10, 12]; // mm

/**
 * @param {number} s_mm    필릿 다리 길이 (mm)
 * @param {number} L_mm    용접 길이 (mm)
 * @param {number} fexx    전극 인장강도 (MPa)
 * @returns {number}       φRn (kN)
 */
export function calcWeldStrength(s_mm, L_mm, fexx = 490) {
  if (s_mm <= 0 || L_mm <= 0) return 0;
  const te = 0.707 * s_mm;
  return 0.75 * 0.60 * fexx * te * L_mm / 1000;
}

/**
 * @param {number} fexx
 * @returns {Array<{ leg_mm, te_mm, phiRn_per10mm }>}
 */
export function buildWeldTable(fexx = 490) {
  return WELD_LEGS.map(s => ({
    leg_mm: s,
    te_mm: +(0.707 * s).toFixed(2),
    phiRn_per10mm: +calcWeldStrength(s, 10, fexx).toFixed(2),
  }));
}

