import { useState, useMemo } from 'react'
import { calcWeldStrength, buildWeldTable, WELD_ELECTRODES } from '../engines/weldStrength'
import UnitInput from '../components/shared/UnitInput'
import ResultBox from '../components/shared/ResultBox'

export default function WeldStrength() {
  const [codeStd,     setCodeStd]     = useState('AISC')   // 'AISC' | 'KDS'
  const [electrodeId, setElectrodeId] = useState('E70')
  const [s, setS] = useState('6')
  const [L, setL] = useState('100')

  const elec  = WELD_ELECTRODES.find(e => e.id === electrodeId)
  const fexx  = elec?.fexx ?? 490
  const table = useMemo(() => buildWeldTable(fexx), [fexx])
  const s_num = parseFloat(s) || 0
  const L_num = parseFloat(L) || 0
  const phiRn = useMemo(() => calcWeldStrength(s_num, L_num, fexx), [s_num, L_num, fexx])

  const te      = +(0.707 * s_num).toFixed(2)
  const fnw     = +(0.60 * fexx).toFixed(1)
  const phiRn_v = +(0.75 * fnw * te * L_num / 1000).toFixed(2)

  return (
    <div>
      <h3 style={titleStyle}>WELDING STRENGTH</h3>
      <p style={descStyle}>AISC 360-16 §J2.4 / KDS 14 31 10 §4.3 — LRFD Fillet Weld (φ = 0.75)</p>

      {/* KDS / AISC code toggle */}
      <div style={{ display: 'flex', gap: 8, marginBottom: 16, alignItems: 'center' }}>
        <span style={{ fontSize: 11, color: 'var(--tx-muted)', marginRight: 4 }}>Design Standard:</span>
        {['KDS', 'AISC'].map(c => (
          <button key={c} onClick={() => setCodeStd(c)} style={{
            padding: '4px 14px', borderRadius: 5, fontSize: 12, fontWeight: 700, cursor: 'pointer',
            border: `1px solid ${codeStd === c ? 'var(--ac-main)' : 'var(--bd-subtle)'}`,
            background: codeStd === c ? 'var(--ac-main)' : 'var(--bg-card)',
            color: codeStd === c ? '#000' : 'var(--tx-secondary)',
          }}>{c}</button>
        ))}
        <span style={{ fontSize: 11, color: 'var(--tx-muted)' }}>
          {codeStd === 'KDS' ? 'KDS 14 31 10 §4.3 — same formula as AISC, φ = 0.75' : 'AISC 360-16 §J2.4'}
        </span>
      </div>

      {/* Electrode selector */}
      <div style={{
        marginBottom: 20, padding: '14px 16px', borderRadius: 8,
        background: 'var(--bg-inset)', border: '1px solid var(--bd-subtle)',
      }}>
        <div style={{ fontSize: 12, fontWeight: 700, color: 'var(--ac-main)', marginBottom: 10, letterSpacing: '0.05em' }}>
          Electrode Selection
        </div>
        <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginBottom: 12 }}>
          {WELD_ELECTRODES.map(e => (
            <button key={e.id} onClick={() => setElectrodeId(e.id)} style={{
              padding: '6px 16px', borderRadius: 6, fontSize: 12, fontWeight: 700, cursor: 'pointer',
              border: '1px solid var(--bd-subtle)',
              background: electrodeId === e.id ? 'var(--ac-main)' : 'var(--bg-card)',
              color: electrodeId === e.id ? '#000' : 'var(--tx-secondary)',
            }}>
              {e.id} — FEXX = {e.fexx} MPa
            </button>
          ))}
        </div>

        {/* Electrode info table */}
        <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
          <thead>
            <tr>
              {['Electrode', 'FEXX (MPa)', 'KS Steel', 'US Steel', 'Application'].map(h => (
                <th key={h} style={infoTh}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {WELD_ELECTRODES.map(e => (
              <tr key={e.id} style={{ background: e.id === electrodeId ? 'var(--bg-active)' : 'transparent', cursor: 'pointer' }}
                onClick={() => setElectrodeId(e.id)}>
                <td style={{ ...infoTd, fontWeight: 700, color: 'var(--ac-main)' }}>{e.name}</td>
                <td style={{ ...infoTd, color: 'var(--val-pos)', fontWeight: 700 }}>{e.fexx}</td>
                <td style={{ ...infoTd, color: 'var(--tx-secondary)' }}>{e.steel_kr}</td>
                <td style={{ ...infoTd, color: 'var(--tx-secondary)' }}>{e.steel_us}</td>
                <td style={infoTd}>{e.note}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div className="grid md:grid-cols-2 gap-8">
        {/* Calculator */}
        <div style={card}>
          <h4 style={cardHead}>{codeStd} Calculator — {elec?.name} (FEXX = {fexx} MPa)</h4>
          <UnitInput id="weld-s" label="Fillet Leg Size s" unit="mm" value={s} onChange={setS} />
          <UnitInput id="weld-L" label="Weld Length L"    unit="mm" value={L} onChange={setL} />

          <ResultBox title="φRn (LRFD)" accent>
            <p style={{ fontSize: 24, fontWeight: 700, color: 'var(--val-pos)', marginBottom: 12 }}>
              {phiRn_v} <span style={{ fontSize: 14, fontWeight: 400, color: 'var(--tx-secondary)' }}>kN</span>
            </p>

            {/* Formula breakdown */}
            <div style={formulaBox}>
              <div style={formulaTitle}>Calculation Basis — {codeStd === 'KDS' ? 'KDS 14 31 10 §4.3' : 'AISC 360-16 §J2.4'}</div>
              <FLine label="Formula" expr="φRn = φ × Fnw × Awe" />
              <FLine label="  Fnw = 0.60 × FEXX" expr={`0.60 × ${fexx} = ${fnw} MPa`} />
              <FLine label="  Awe = te × L" expr={`te × L`} />
              <hr style={hr} />
              <FLine label="φ" expr="0.75 (LRFD)" />
              <FLine label={`FEXX (${elec?.name})`} expr={`${fexx} MPa`} />
              <FLine label="Fnw" expr={`0.60 × ${fexx} = ${fnw} MPa`} />
              <FLine label={`te (s = ${s_num} mm)`} expr={`0.707 × ${s_num} = ${te} mm`} />
              <FLine label={`L`} expr={`${L_num} mm`} />
              <hr style={hr} />
              <FLine
                label="φRn"
                expr={`0.75 × ${fnw} × ${te} × ${L_num} / 1000 = ${phiRn_v} kN`}
                highlight
              />
            </div>
          </ResultBox>
        </div>

        {/* Reference table */}
        <div>
          <h4 style={{ fontSize: 13, fontWeight: 700, marginBottom: 10, color: 'var(--ac-main)' }}>
            Strength Table per 10mm weld length ({elec?.name})
          </h4>
          <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 13 }}>
            <thead>
              <tr>
                <th style={th}>Leg (mm)</th>
                <th style={th}>te (mm)</th>
                <th style={th}>φRn / 10mm (kN)</th>
              </tr>
            </thead>
            <tbody>
              {table.map(row => (
                <tr key={row.leg_mm} style={{
                  background: s_num === row.leg_mm ? 'var(--bg-active)' : 'transparent',
                }}>
                  <td style={{ ...td, fontWeight: 700, color: 'var(--tx-primary)' }}>{row.leg_mm} mm</td>
                  <td style={{ ...td, color: 'var(--tx-secondary)' }}>{row.te_mm}</td>
                  <td style={{ ...td, color: 'var(--val-pos)', fontWeight: 700 }}>{row.phiRn_per10mm}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  )
}

function FLine({ label, expr, highlight }) {
  return (
    <div style={{ display: 'flex', justifyContent: 'space-between', padding: '3px 0', fontSize: 12, gap: 12 }}>
      <span style={{ color: 'var(--tx-secondary)', flexShrink: 0 }}>{label}</span>
      <span style={{
        fontWeight: highlight ? 700 : 500,
        color: highlight ? 'var(--val-pos)' : 'var(--tx-primary)',
        fontFamily: 'monospace', textAlign: 'right',
      }}>{expr}</span>
    </div>
  )
}

const titleStyle  = { fontSize: '1.3rem', fontWeight: 700, marginBottom: 8, color: 'var(--tx-primary)', paddingBottom: 10, borderBottom: '1px solid var(--bd-subtle)' }
const descStyle   = { marginBottom: 20, color: 'var(--tx-secondary)', fontSize: 13 }
const card        = { background: 'var(--bg-card)', border: '1px solid var(--bd-accent)', borderRadius: 10, padding: 20 }
const cardHead    = { fontSize: 13, fontWeight: 700, marginBottom: 14, color: 'var(--ac-main)' }
const th          = { background: 'var(--bg-inset)', color: 'var(--ac-main)', fontWeight: 600, padding: '9px 12px', textAlign: 'left', borderBottom: '2px solid var(--bd-accent)' }
const td          = { padding: '8px 12px', borderBottom: '1px solid var(--bd-subtle)' }
const infoTh      = { background: 'var(--bg-card)', color: 'var(--tx-secondary)', fontWeight: 600, padding: '6px 10px', textAlign: 'left', borderBottom: '1px solid var(--bd-subtle)', fontSize: 11 }
const infoTd      = { padding: '5px 10px', borderBottom: '1px solid var(--bd-subtle)', color: 'var(--tx-primary)', fontSize: 12 }
const formulaBox  = { background: 'var(--bg-inset)', borderRadius: 6, padding: '10px 14px', marginTop: 8, border: '1px solid var(--bd-subtle)' }
const formulaTitle= { fontSize: 11, fontWeight: 700, color: 'var(--ac-main)', marginBottom: 8, letterSpacing: '0.05em' }
const hr          = { border: 'none', borderTop: '1px solid var(--bd-subtle)', margin: '6px 0' }
